/**
 * Canonical Artifact Reference Contracts.
 *
 * Represents an external asset or file generated by an agent execution.
 */

import { z } from "zod";

export const artifactReferenceSchema = z.object({
  artifact_id: z.string(),
  step_id: z.string().optional(),
  name: z.string(),
  type: z.string(),                              // MIME type or semantic category (e.g. "report_markdown", "application/pdf")
  uri: z.string().optional(),                    // file path, S3 URI, or storage link
  size_bytes: z.number().int().nonnegative().optional(),
  hash: z.string().optional(),                   // SHA-256 integrity hash
  created_at: z.string(),
  metadata: z.record(z.string(), z.unknown()).optional(),
});

export type ArtifactReference = z.infer<typeof artifactReferenceSchema>;
